"""Factorized imaginary inverse and minimal dual quotient with certified solves.

The source loader must authenticate the local factors and the frozen certificate
linking R0, E=I-R0*B, selected rows and dyadic scales. Numerical candidates never
define the inverse: every solve includes the certified Neumann remainder.
"""


def _matrix(reference,rows,columns,values=None):
    return type(reference)(rows,columns) if values is None else type(reference)(rows,columns,values)


def _sym(A):return (A+A.transpose())/2


def _column_blocks(matrices,node):
    ref=matrices[0]
    return _matrix(ref,ref.nrows(),len(matrices),
        [A[i,node] for i in range(ref.nrows()) for A in matrices])


def _put_column_blocks(matrices,node,block):
    for i in range(block.nrows()):
        for k,A in enumerate(matrices):A[i,node]=block[i,k]


def congruence_batch(left,matrices,right):
    """Two native dense products; the Python work is only O(M^2 K)."""
    if not matrices:return []
    M=left.nrows();K=len(matrices)
    horizontal=_matrix(left,M,M*K,[A[i,j] for i in range(M) for A in matrices for j in range(M)])
    work=left*horizontal
    vertical=_matrix(left,M*K,M,[work[i,k*M+j] for k in range(K) for i in range(M) for j in range(M)])
    work=vertical*right
    return [_matrix(left,M,M,[work[k*M+i,j] for i in range(M) for j in range(M)]) for k in range(K)]


class CertifiedSelectedSolve:
    """RHS-specific enclosure of the TRUE selected inverse; zero corrections."""
    def __init__(self,R0,delta,row_scales,column_scales):
        from flint import arb
        self.R0=R0;self.delta=delta;self.n=R0.nrows()
        if self.n!=R0.ncols() or len(row_scales)!=self.n or len(column_scales)!=self.n:
            raise ValueError('Complete square candidate and all dyadic scales required')
        if not delta.is_finite() or not delta>=0 or not delta<1:raise ValueError('A strict certified residual bound is required')
        if not all(R0[i,j].is_exact() and R0[i,j].is_finite() for i in range(self.n) for j in range(self.n)):
            raise ValueError('R0 must be a finite exact dyadic matrix')
        if not all(s.is_exact() and s.is_finite() and s>0 for s in list(row_scales)+list(column_scales)):
            raise ValueError('Finite positive exact dyadic conditioning scales required')
        self.dr=list(row_scales);self.dc=list(column_scales)
        self.norm_R0=max(sum((abs(R0[i,j]) for j in range(self.n)),arb(0)).upper() for i in range(self.n))

    def _scale_rows(self,A,scales):
        return _matrix(A,A.nrows(),A.ncols(),[scales[i]*A[i,k] for i in range(A.nrows()) for k in range(A.ncols())])

    def forward(self,rhs):
        """Dc B^-1 Dr rhs; preserve the input box and add a per-column tail."""
        from flint import arb
        if rhs.nrows()!=self.n:raise ValueError('All selected RHS coordinates required')
        c=self._scale_rows(rhs,self.dr);x0=self.R0*c
        maxima=[max(abs(x0[i,k]).upper() for i in range(self.n)) for k in range(rhs.ncols())]
        tails=[(self.delta/(1-self.delta)*m).upper() for m in maxima]
        enclosed=_matrix(x0,self.n,rhs.ncols(),
            [x0[i,k]+arb(0,tails[k]) for i in range(self.n) for k in range(rhs.ncols())])
        return self._scale_rows(enclosed,self.dc),dict(
            method='x0=R0*c; ||u-x0||inf<=delta/(1-delta)*sup_box||x0||inf',
            true_inverse_enclosed=True,neumann_corrections=0,
            pre_tail_solution=self._scale_rows(x0,self.dc),
            x0_maximum_absolute_value=maxima,neumann_tail_unscaled=tails,
            x0_maximum_radius=[max(x0[i,k].rad() for i in range(self.n)) for k in range(rhs.ncols())],
            component_tail_after_column_scaling=[[self.dc[i]*tails[k] for i in range(self.n)] for k in range(rhs.ncols())])

    def transpose(self,rhs):
        """Dr B^-T Dc rhs; the transpose tail uses a 1-norm bound."""
        from flint import arb
        if rhs.nrows()!=self.n:raise ValueError('All adjoint RHS coordinates required')
        v=self._scale_rows(rhs,self.dc);y0=self.R0.transpose()*v
        vnorm=[sum((abs(v[i,k]) for i in range(self.n)),arb(0)).upper() for k in range(rhs.ncols())]
        tails=[(self.norm_R0*self.delta/(1-self.delta)*m).upper() for m in vnorm]
        enclosed=_matrix(y0,self.n,rhs.ncols(),
            [y0[i,k]+arb(0,tails[k]) for i in range(self.n) for k in range(rhs.ncols())])
        return self._scale_rows(enclosed,self.dr),dict(
            method='B^-T=R0^T*(I-E^T)^-1; ||tail||1<=||R0||inf*delta/(1-delta)*||v||1',
            true_inverse_enclosed=True,neumann_corrections=0,neumann_tail_unscaled=tails)


class FactorizedImaginaryProjection:
    """Block apply/adjoint and the exact 1+(2825-450) source quotient."""
    def __init__(self,factors,selected_rows,solver):
        self.f=factors;self.T=factors.T;self.M=self.T.nrows();self.e=factors.E[0].ncols();self.L=self.e+1
        M=self.M;self.selected=list(selected_rows);self.solver=solver
        self.sym_pairs=[(i,j) for i in range(M) for j in range(i,M)]
        self.full_rows=M*M+len(self.sym_pairs);self.alpha_count=M*self.e
        if len(self.selected)!=self.alpha_count or len(set(self.selected))!=self.alpha_count:
            raise ValueError('All distinct certified selected rows required')
        self.structural_zero={j*M+i for j,rows in enumerate(factors.selectors) for i in rows}
        if self.structural_zero.intersection(self.selected):raise ValueError('A selected row cannot be a proved identity')
        if any(not 0<=i<self.full_rows for i in self.selected):raise ValueError('Selected row outside full residual')
        self.free=[i for i in range(self.full_rows) if i not in self.structural_zero and i not in self.selected]
        self.coefficient_count=1+2*M+M*M+M*(M+1)//2
        self.quotient_count=1+len(self.free)
        self.metadata=dict(M=M,even_nonS=self.e,rows=self.full_rows,alpha_count=self.alpha_count,
            structural_zero_rows=sorted(self.structural_zero),selected_exact_zero_rows=self.selected,
            free_residual_rows=self.free,quotient_count=self.quotient_count,
            quotient_order='constant, unselected active membership, unselected Sym uppertriangle',
            membership_quotient_scale=32,symmetry_quotient_scale=64,
            constant_preserved=True,single_family_projected_columns_exact_zero=True,
            physical_G_scales_cancel_in_projector=True)

    def _check(self,rows,count):
        if type(rows)!=type(self.T) or rows.nrows()!=count:raise ValueError('Complete matching-backend block required')

    def _split(self,rows,*,primal=False):
        M=self.M;K=rows.ncols();at=1
        a=_matrix(self.T,M,K,[rows[at+i,k] for i in range(M) for k in range(K)]);at+=M
        b=_matrix(self.T,M,K,[rows[at+i,k] for i in range(M) for k in range(K)]);at+=M
        B=[_matrix(self.T,M,M,[rows[at+i,k] for i in range(M*M)]) for k in range(K)];at+=M*M
        C=[_matrix(self.T,M,M) for _ in range(K)]
        for i in range(M):
            for j in range(i,M):
                for k in range(K):C[k][i,j]=C[k][j,i]=rows[at,k]/(2 if primal and i!=j else 1)
                at+=1
        return a,b,B,C

    def _weighted_S(self,weights):
        M=self.M
        return [_matrix(self.T,M,M,[self.f.W0[i,j]*weights[j,k] for i in range(M) for j in range(M)])
                for k in range(weights.ncols())]

    def _columnwise(self,maps,matrices):
        M=self.M;out=[_matrix(self.T,M,M) for _ in matrices]
        for j in range(M):_put_column_blocks(out,j,maps[j]*_column_blocks(matrices,j))
        return out

    def _rhs(self,A,H):
        M=self.M;K=len(A)
        membership=self._columnwise(self.f.membership,A);signed=self._columnwise(self.f.signed,A)
        sym=[H[k]-_sym(signed[k]) for k in range(K)]
        values=[]
        for j in range(M):
            for i in range(M):values.extend(membership[k][i,j]/3 for k in range(K))
        for i,j in self.sym_pairs:values.extend(sym[k][i,j] for k in range(K))
        rhs=_matrix(self.T,self.full_rows,K,values)
        for row in self.structural_zero:
            for k in range(K):rhs[row,k]=self.T[0,0]*0
        return rhs

    def _prepare(self,rows):
        self._check(rows,self.coefficient_count);K=rows.ncols();M=self.M
        ra,rb,rB,rC=self._split(rows)
        alpha0=2*self.f.TinvT*ra/3;beta0=self.f.TinvT*rb
        P0=self._weighted_S(alpha0);Q0=self._weighted_S(beta0)
        Bhat=congruence_batch(self.f.TinvT,rB,self.f.Tinv)
        Chat=congruence_batch(self.f.TinvT,rC,self.f.Tinv)
        A=[Bhat[k]/2-3*P0[k].transpose()-Q0[k] for k in range(K)]
        H=[Chat[k]/2-_sym(Q0[k]) for k in range(K)]
        rhs=self._rhs(A,H)
        selected=_matrix(self.T,self.alpha_count,K,[rhs[i,k] for i in self.selected for k in range(K)])
        alpha,solve_report=self.solver.forward(selected)
        P=[_matrix(self.T,M,M) for _ in range(K)]
        for j in range(M):
            block=_matrix(self.T,self.e,K,[alpha[j*self.e+i,k] for i in range(self.e) for k in range(K)])
            _put_column_blocks(P,j,self.f.E[j]*block)
        y=[A[k]-3*P[k].transpose() for k in range(K)]
        return dict(alpha0=alpha0,beta0=beta0,alpha=alpha,A=A,H=H,y=y,solve_report=solve_report)

    def _weights(self,state):
        M,L,e=self.M,self.L,self.e;K=state['alpha'].ncols();values=[]
        for j in range(M):
            z=self.f.local[j]*_column_blocks(state['y'],j)
            values.extend(state['alpha0'][j,k] for k in range(K))
            for a in range(e):values.extend(state['alpha'][j*e+a,k] for k in range(K))
            values.extend(state['beta0'][j,k] for k in range(K))
            for a in range(e):values.extend(z[a,k] for k in range(K))
            for a in range(L):values.extend(z[e+a,k] for k in range(K))
        return _matrix(self.T,M*3*L,K,values)

    def left_apply_f(self,rows):
        state=self._prepare(rows)
        return self._weights(state),state['solve_report']

    def left_apply_physical(self,rows,*,kappa=None):
        """Physical isospin dual order; kappa=None denotes f rather than G."""
        weights,report=self.left_apply_f(rows);M,L=self.M,self.L;K=rows.ncols()
        scales=[self.T[0,0]*0+1]*M if kappa is None else list(kappa)
        if len(scales)!=M or any(not s>0 for s in scales):raise ValueError('Positive row normalization required')
        out=_matrix(self.T,M*3*L,K)
        for j in range(M):
            base=j*3*L
            for a in range(L):
                for k in range(K):
                    aa=weights[base+a,k];bb=weights[base+L+a,k];gg=weights[base+2*L+a,k]
                    out[base+a,k]=aa/scales[j];out[base+L+a,k]=gg/scales[j]
                    out[base+2*L+a,k]=(bb-aa)/scales[j]
        return out,report

    def quotient(self,rows,*,include_weights=False):
        state=self._prepare(rows);K=rows.ncols()
        # _rhs(y,H) equals b-F*alpha, with the correct unchanged Sym packing.
        residual=self._rhs(state['y'],state['H'])
        # These identities refer to the exact inverse enclosed by the solver;
        # the approximate candidate alone would not justify this assignment.
        if not state['solve_report'].get('true_inverse_enclosed'):
            raise ValueError('A true-inverse enclosure is required before assigning selected identities')
        for row in self.selected:
            for k in range(K):residual[row,k]=self.T[0,0]*0
        values=[rows[0,k] for k in range(K)]
        for row in self.free:
            scale=32 if row<self.M*self.M else 64
            values.extend(scale*residual[row,k] for k in range(K))
        output=dict(quotient=_matrix(self.T,self.quotient_count,K,values),alpha=state['alpha'],
            solve_report=state['solve_report'],full_residual=residual)
        if include_weights:output['weights_DEV_f']=self._weights(state)
        return output

    def reconstruct_projected_rows(self,q):
        self._check(q,self.quotient_count);M=self.M;K=q.ncols()
        residual=_matrix(self.T,self.full_rows,K)
        for i,row in enumerate(self.free):
            scale=32 if row<M*M else 64
            for k in range(K):residual[row,k]=q[i+1,k]/scale
        mem=[_matrix(self.T,M,M,[residual[j*M+i,k] for i in range(M) for j in range(M)]) for k in range(K)]
        sym=[_matrix(self.T,M,M) for _ in range(K)]
        for index,(i,j) in enumerate(self.sym_pairs):
            for k in range(K):sym[k][i,j]=sym[k][j,i]=residual[M*M+index,k]
        B=[6*A*self.T for A in mem]
        C=[2*A for A in congruence_batch(self.T.transpose(),sym,self.T)]
        out=_matrix(self.T,self.coefficient_count,K)
        for k in range(K):out[0,k]=q[0,k]
        at=1+2*M
        for i in range(M):
            for j in range(M):
                for k in range(K):out[at,k]=B[k][i,j]
                at+=1
        for i in range(M):
            for j in range(i,M):
                for k in range(K):out[at,k]=C[k][i,j]
                at+=1
        return out

    def project_rows(self,rows):
        result=self.quotient(rows)
        result['projected_rows']=self.reconstruct_projected_rows(result['quotient'])
        return result

    def right_apply_f(self,targets):
        """Explicit adjoint for node-major (D,E,V) f targets, no full R matrix."""
        M,L,e=self.M,self.L,self.e;self._check(targets,M*3*L);K=targets.ncols()
        Ybar=[_matrix(self.T,M,M) for _ in range(K)]
        for j in range(M):
            base=j*3*L
            z=_matrix(self.T,e+L,K,
                [targets[base+L+1+a,k] for a in range(e) for k in range(K)]
                +[targets[base+2*L+a,k] for a in range(L) for k in range(K)])
            _put_column_blocks(Ybar,j,self.f.local[j].transpose()*z)
        abar=_matrix(self.T,M*e,K)
        for j in range(M):
            correction=-3*self.f.E[j].transpose()*_column_blocks([A.transpose() for A in Ybar],j)
            for a in range(e):
                for k in range(K):abar[j*e+a,k]=targets[j*3*L+1+a,k]+correction[a,k]
        selected_bar,solve_report=self.solver.transpose(abar)
        rhsbar=_matrix(self.T,self.full_rows,K)
        for i,row in enumerate(self.selected):
            for k in range(K):rhsbar[row,k]=selected_bar[i,k]
        V=[_matrix(self.T,M,M) for _ in range(K)]
        for index,(i,j) in enumerate(self.sym_pairs):
            for k in range(K):V[k][i,j]=V[k][j,i]=rhsbar[M*M+index,k]/(1 if i==j else 2)
        Abar=[_matrix(self.T,M,M,list(A.entries())) for A in Ybar]
        for j in range(M):
            u=_matrix(self.T,M,K,[rhsbar[j*M+i,k] for i in range(M) for k in range(K)])
            correction=self.f.membership[j].transpose()*u/3-self.f.signed[j].transpose()*_column_blocks(V,j)
            for i in range(M):
                for k in range(K):Abar[k][i,j]+=correction[i,k]
        a0bar=_matrix(self.T,M,K);b0bar=_matrix(self.T,M,K)
        for j in range(M):
            for k in range(K):
                a0bar[j,k]=targets[j*3*L,k]-3*sum(self.f.W0[i,j]*Abar[k][j,i] for i in range(M))
                b0bar[j,k]=targets[j*3*L+L,k]-sum(self.f.W0[i,j]*(Abar[k][i,j]+V[k][i,j]) for i in range(M))
        a=2*self.f.Tinv*a0bar/3;b=self.f.Tinv*b0bar
        B=[A/2 for A in congruence_batch(self.f.Tinv,Abar,self.f.TinvT)]
        C=[A/2 for A in congruence_batch(self.f.Tinv,V,self.f.TinvT)]
        out=_matrix(self.T,self.coefficient_count,K)
        at=1
        for block in (a,b):
            for i in range(M):
                for k in range(K):out[at,k]=block[i,k]
                at+=1
        for i in range(M):
            for j in range(M):
                for k in range(K):out[at,k]=B[k][i,j]
                at+=1
        for i in range(M):
            for j in range(i,M):
                for k in range(K):out[at,k]=C[k][i,j] if i==j else 2*C[k][i,j]
                at+=1
        return out,solve_report

    def right_apply_physical(self,targets,*,kappa=None):
        """Physical isospin target order, with explicit f/G row conversion."""
        M,L=self.M,self.L;self._check(targets,M*3*L);K=targets.ncols()
        scales=[self.T[0,0]*0+1]*M if kappa is None else list(kappa)
        if len(scales)!=M or any(not s>0 for s in scales):raise ValueError('Positive row normalization required')
        dev=_matrix(self.T,M*3*L,K)
        for j in range(M):
            base=j*3*L
            for a in range(L):
                for k in range(K):
                    dev[base+a,k]=(targets[base+a,k]-targets[base+2*L+a,k])/scales[j]
                    dev[base+L+a,k]=targets[base+2*L+a,k]/scales[j]
                    dev[base+2*L+a,k]=targets[base+L+a,k]/scales[j]
        return self.right_apply_f(dev)
